const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process'),assert=require('node:assert/strict');
const root=path.resolve(__dirname,'..');

const read=p=>fs.readFileSync(path.join(root,p),'utf8');

// Web must already be generated by scripts/build-web.mjs in CI.
// Generate the exact Capacitor payload from that reviewed web client, then compare
// the transport/signaling core across Windows, Web/PWA, Android and iOS source payloads.
cp.execFileSync(process.execPath,[path.join(root,'mobile/scripts/sync-web.mjs')],{cwd:root,stdio:'inherit'});

const desktop=read('desktop/desktop-client.html');
const web=read('index.html');
const mobile=read('mobile/www/index.html');

function lineWith(source,marker,label){
  const line=source.split(/\r?\n/).find(row=>row.includes(marker));
  assert(line, label+' missing '+marker);
  return line.trim();
}

const parityMarkers=[
  'async function restartVoicePeer(peerId)',
  'function voicePeer(peerId)',
  'async function recoverVoiceSignals()',
  'async function subscribeVoiceSignals()',
  'async function consumeVoiceSignalRow(row)',
  'async function sendVoiceSignal(to,data)',
  'async function syncVoicePeers()',
  'async function handleVoiceSignal(msg)',
  'async function refreshVoiceParticipants(id)',
  'async function refreshVoiceRosterSet(chs=voiceChannelDefs,force=false)',
  'function subscribeVoiceParticipants()',
  'function ensureVoiceRooms(chs)',
  'function startVoiceHeartbeat()',
  'async function trackVoicePresence()',
  'function ycStartRemoteVoiceActivityDetector(peerId,stream)'
];

for(const marker of parityMarkers){
  const d=lineWith(desktop,marker,'Windows');
  const w=lineWith(web,marker,'Web/PWA');
  const m=lineWith(mobile,marker,'Mobile');
  assert.equal(w,d,'Windows ↔ Web/PWA voice core drifted at '+marker);
  assert.equal(m,w,'Web/PWA ↔ Android/iOS voice core drifted at '+marker);
}

for(const [name,source] of [['Windows',desktop],['Web/PWA',web],['Android/iOS',mobile]]){
  for(const marker of [
    "filter:'to_user=eq.'+uid",
    "payload.from_session&&sender?.session_id&&payload.from_session!==sender.session_id",
    "String(user.id)<String(p.user_id)",
    "iceTransportPolicy:'all'",
    "iceCandidatePoolSize:8",
    "bundlePolicy:'max-bundle'",
    "['CHANNEL_ERROR','TIMED_OUT','CLOSED'].includes(status)",
    "YC_VOICE_TTL_MS=120000",
    "event:'INSERT',schema:'public',table:'voice_participants',filter",
    "event:'DELETE',schema:'public',table:'voice_participants',filter",
    ".in('channel_id',ids).gt('last_seen',cutoff)",
    "void syncVoiceParticipantRow().catch(e=>console.warn('voice participant keepalive',e))",
    "function ycStartRemoteVoiceActivityDetector(peerId,stream)",
    "lt('created_at',stale)",
    "gt('created_at',recent)",
    "voiceSignalSub===sub&&String(user?.id||'')===uid",
    "void recoverVoiceSignals()",
    "yamachat-turn-cloudflare"
  ]) assert(source.includes(marker),name+' missing interoperability marker: '+marker);

  assert(!source.includes("event:'*',schema:'public',table:'voice_participants'"),name+' still globally fans out participant heartbeats');
  assert(!source.includes("config:{presence:{key:user.id}"),name+' still configures voice Realtime Presence');
  assert(!source.includes(".on('presence'"),name+' still listens to voice Realtime Presence');
  assert(!source.includes("room.track("),name+' still calls Realtime Presence track()');
  assert(!source.includes("room?.untrack("),name+' still calls Realtime Presence untrack()');
  assert(!source.includes("sb.functions.invoke('yamachat-turn',{method:'GET'})"),name+' still loads Metered TURN');
  assert(!source.includes("syncVoiceParticipantRow().catch(()=>{});renderVoiceChannels(voiceChannelDefs)"),name+' still persists speaking transitions to Postgres');
  assert(!source.includes("if(pc?.connectionState==='connected'){voiceMissingSince.delete(id);continue}"),name+' keeps ghost peers alive while RTC still reports connected');
  assert(source.includes("const since=voiceMissingSince.get(id)||now;voiceMissingSince.set(id,since);if(now-since>60000)closeVoicePeer(id)"),name+' missing roster-lease peer cleanup grace');
}

const pkg=JSON.parse(read('desktop/package.json'));
assert(pkg.build.files.includes('boot-guard.js'),'Windows package must contain boot-guard.js');
const boot=read('boot-guard.js');
assert(boot.includes('isTransientNetworkRejection'),'Boot guard transient-network classification missing');
const sw=read('sw.js');
assert(sw.includes("const CACHE='yamachat-web-voice-recovery-20260928-103';"),'PWA cache was not bumped for the recovery fix');

console.log('PASS cross-platform voice interop: Windows, Web/PWA, Android and iOS share signaling/ICE/session/reconnect invariants.');
